<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$eventId=(int)($_GET['event_id']??0);$events=pg_query($conn,'SELECT id,title,start_at,status FROM events ORDER BY start_at DESC');$event=null;if($eventId){$r=pg_query_params($conn,'SELECT * FROM events WHERE id=$1',[$eventId]);$event=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;}
function report_rows($conn,$eventId){return pg_query_params($conn,"SELECT a.attendee_code,a.full_name,a.email,a.phone,a.organization,r.ticket_code,r.status registration_status,r.registered_at,COALESCE(MIN(sa.time_in_at),ar.check_in_at) check_in_at,COALESCE(MAX(sa.time_out_at),ar.check_out_at) check_out_at,COALESCE(ar.check_in_method,'session') check_in_method,CASE WHEN COALESCE(MAX(sa.time_out_at),ar.check_out_at) IS NOT NULL AND COALESCE(MIN(sa.time_in_at),ar.check_in_at) IS NOT NULL THEN EXTRACT(EPOCH FROM(COALESCE(MAX(sa.time_out_at),ar.check_out_at)-COALESCE(MIN(sa.time_in_at),ar.check_in_at)))::integer END duration_seconds,string_agg(DISTINCT CASE WHEN sa.time_in_at IS NOT NULL THEN initcap(es.session_name) END,', ') sessions_present FROM event_registrations r JOIN attendees a ON a.id=r.attendee_id LEFT JOIN attendance_records ar ON ar.registration_id=r.id LEFT JOIN event_sessions es ON es.event_id=r.event_id LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=es.id WHERE r.event_id=$1 GROUP BY a.id,r.id,ar.id ORDER BY a.full_name",[$eventId]);}
if($event&&($_GET['export']??'')==='csv'){$rows=report_rows($conn,$eventId);$safe=preg_replace('/[^A-Za-z0-9_-]+/','-',strtolower($event['title']));header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="attendance-'.$safe.'.csv"');$out=fopen('php://output','w');fputs($out,"\xEF\xBB\xBF");fputcsv($out,['Student ID','Full Name','Email','Phone','Course / Section','Ticket','Registration Status','Registered At','First Time In','Last Time Out','Sessions Present','Duration Minutes']);while($a=pg_fetch_assoc($rows))fputcsv($out,[$a['attendee_code'],$a['full_name'],$a['email'],$a['phone'],$a['organization'],$a['ticket_code'],$a['registration_status'],$a['registered_at'],$a['check_in_at'],$a['check_out_at'],$a['sessions_present'],$a['duration_seconds']!==null?round($a['duration_seconds']/60,1):'']);fclose($out);audit_log($conn,'attendance_report_exported','event',$eventId);exit;}
require_once __DIR__.'/../../includes/admin_layout.php';$rows=$event?report_rows($conn,$eventId):null;$stats=$event?pg_query_params($conn,"SELECT COUNT(DISTINCT r.id) FILTER(WHERE r.status='registered') registered,COUNT(DISTINCT r.id) FILTER(WHERE r.status='waitlisted') waitlisted,COUNT(DISTINCT r.id) FILTER(WHERE sa.time_in_at IS NOT NULL OR ar.id IS NOT NULL) attended,COUNT(DISTINCT r.id) FILTER(WHERE sa.time_out_at IS NOT NULL OR ar.check_out_at IS NOT NULL) completed,MIN(COALESCE(sa.time_in_at,ar.check_in_at)) first_checkin,MAX(COALESCE(sa.time_in_at,ar.check_in_at)) last_checkin FROM event_registrations r LEFT JOIN attendance_records ar ON ar.registration_id=r.id LEFT JOIN event_sessions es ON es.event_id=r.event_id LEFT JOIN session_attendance sa ON sa.registration_id=r.id AND sa.session_id=es.id WHERE r.event_id=$1",[$eventId]):null;$sum=$stats?pg_fetch_assoc($stats):['registered'=>0,'waitlisted'=>0,'attended'=>0,'completed'=>0];$rate=(int)$sum['registered']?round((int)$sum['attended']/(int)$sum['registered']*100,1):0;admin_page_start('Attendance Reports','reports');?>
<div class="hero"><div><h2><i class="fas fa-chart-column"></i> Attendance Reports</h2><p>Review turnout, arrival activity, and export event-level attendance records.</p></div><?php if($event):?><a class="btn" href="?event_id=<?=$eventId?>&export=csv"><i class="fas fa-download"></i> Export CSV</a><?php endif;?></div>
<div class="card"><form method="get" class="form-grid"><div class="field full"><label>Event</label><select name="event_id" onchange="this.form.submit()"><option value="">Choose an event…</option><?php if($events):while($e=pg_fetch_assoc($events)):?><option value="<?=(int)$e['id']?>" <?=$eventId===(int)$e['id']?'selected':''?>><?=h($e['title'])?> · <?=h(date('M j, Y',strtotime($e['start_at'])))?> (<?=h($e['status'])?>)</option><?php endwhile;endif;?></select></div></form></div>
<?php if($event):?><div class="stats-grid"><div class="stat-card voters"><div class="stat-icon"><i class="fas fa-ticket"></i></div><div><div class="stat-number"><?=(int)$sum['registered']?></div><div class="stat-label">Registered</div><div class="stat-sub"><?=(int)$sum['waitlisted']?> waitlisted</div></div></div><div class="stat-card votes"><div class="stat-icon"><i class="fas fa-user-check"></i></div><div><div class="stat-number"><?=(int)$sum['attended']?></div><div class="stat-label">Attended</div></div></div><div class="stat-card turnout"><div class="stat-icon"><i class="fas fa-percent"></i></div><div><div class="stat-number"><?=$rate?>%</div><div class="stat-label">Attendance Rate</div></div></div><div class="stat-card positions"><div class="stat-icon"><i class="fas fa-person-walking-arrow-right"></i></div><div><div class="stat-number"><?=(int)$sum['completed']?></div><div class="stat-label">Checked Out</div></div></div></div>
<div class="card"><h3><?=h($event['title'])?></h3><p class="help"><?=h(date('F j, Y · g:i A',strtotime($event['start_at'])))?> to <?=h(date('g:i A',strtotime($event['end_at'])))?> · <?=h($event['venue']?:'Venue TBA')?><?php if(!empty($sum['first_checkin'])):?> · Check-ins from <?=h(date('g:i A',strtotime($sum['first_checkin'])))?> to <?=h(date('g:i A',strtotime($sum['last_checkin'])))?><?php endif;?></p><div class="table-wrap"><table><thead><tr><th>Attendee</th><th>Organization</th><th>Registration</th><th>Check-in</th><th>Check-out</th><th>Duration</th></tr></thead><tbody><?php if($rows):while($a=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($a['full_name'])?></strong><div class="help"><?=h($a['attendee_code'])?> · <?=h($a['email']?:'No email')?></div></td><td><?=h($a['organization']?:'—')?></td><td><span class="badge <?=h($a['registration_status'])?>"><?=h(ucfirst($a['registration_status']))?></span><div class="help"><?=h($a['ticket_code'])?></div></td><td><?=$a['check_in_at']?h(date('M j, g:i:s A',strtotime($a['check_in_at']))):'Absent'?></td><td><?=$a['check_out_at']?h(date('M j, g:i:s A',strtotime($a['check_out_at']))):'—'?></td><td><?=$a['duration_seconds']!==null?round((int)$a['duration_seconds']/60).' min':'—'?></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="6" class="empty">No registrations for this event.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
<?php admin_page_end();?>
